import { test, expect } from '@playwright/test';

test.describe('Conflict Error Message on Stale Record Save', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display conflict error message when saving a stale record', async ({ page }) => {
    // Get the record by role
    const recordItem = page.getByRole('region', { name: /record/i });
    await recordItem.click();

    // Get the save button by role
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();

    // Click save button to trigger save operation
    await saveButton.click();

    // Wait for conflict error message to appear
    const errorMessage = page.getByText(/record is stale/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message contains specific text
    await expect(errorMessage).toContainText('Record is stale');

    // Verify error message is visible and styled appropriately
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toHaveClass(/error-message/i);

    // Verify save button is disabled
    await expect(saveButton).toBeDisabled();

    // Verify error message has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button is clickable
    await expect(closeButton).toBeEnabled();

    // Click close button to dismiss error
    await closeButton.click();

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();

    // Verify record item is still visible
    await expect(recordItem).toBeVisible();
  });

  test('should not display error message when saving a fresh record', async ({ page }) => {
    // Get the record by role
    const recordItem = page.getByRole('region', { name: /record/i });
    await recordItem.click();

    // Get the save button by role
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();

    // Click save button to trigger save operation
    await saveButton.click();

    // Wait for success message to appear
    const successMessage = page.getByText(/record saved successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify success message is visible and styled appropriately
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toHaveClass(/success-message/i);

    // Verify save button is enabled
    await expect(saveButton).toBeEnabled();

    // Verify success message has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button is clickable
    await expect(closeButton).toBeEnabled();

    // Click close button to dismiss success message
    await closeButton.click();

    // Verify success message is no longer visible
    await expect(successMessage).not.toBeVisible();

    // Verify record item is still visible
    await expect(recordItem).toBeVisible();
  });
});
